ask()  { # ask "вопрос" -> 0 если ответ «да»; по умолчанию «нет»
  local a; read -r -p "$1 [y/N] " a </dev/tty || return 1
  case "$a" in y|Y|д|Д|да|Да|yes) return 0 ;; *) return 1 ;; esac
}

ROOT=0; [ "$(id -u)" -eq 0 ] && ROOT=1
T=20      # сколько секунд ждать одну команду


have() { command -v "$1" >/dev/null 2>&1; }
sec()  { printf '\n===== %s =====\n' "$1"; }

runroot() {
  if [ "$ROOT" -ne 1 ]; then echo "\$ $*"; echo "(нужен root, пропущено)"; return 0; fi
  run "$@"
}

pipe() {
  echo "\$ $1"
  timeout "$T" bash -c "$1" 2>&1
  [ $? -eq 124 ] && echo "(не завершилась за $T с, остановлена)"
  return 0
}

run() {
	printf '\n$ %s\n' "$*"
	timeout "$T" bash -c "$*" 2>&1 | head -n 60
	local c=${PIPESTATUS[0]}
	[ "$c" = 124 ] && echo "[зависло дольше $T с — прервано]"
	echo "[код $c]"
}
